-- 栈基础：仅在栈顶操作的 LIFO 语义。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '栈的 LIFO 语义与基本操作','栈只允许在栈顶插入和删除，最后压入的元素最先弹出。',course.id,parent.id,'cs408-stack-lifo','AISTU',1,'REVIEWED',1,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-stack-lifo' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-stack-lifo',1,'REVIEWED','栈的 LIFO 语义与基本操作',JSON_OBJECT('summary','栈是只在一端插入和删除的受限线性表；这一端是栈顶，另一端是栈底。push 压入，pop 删除并返回栈顶，top 只读取栈顶；空栈的 pop 或 top 必须按接口规则处理下溢。','steps',JSON_ARRAY('栈顶是唯一允许更新的端','push 在栈顶压入新元素','pop 从栈顶删除并返回元素','top 只读取栈顶，不改变结构','空栈操作必须先处理下溢'),'prerequisite',JSON_OBJECT('contentKey','cs408-linear-list-definition-operations','title','线性表的定义与基本操作','description','先理解栈仍是一种受限的线性表 ADT。'),'nextStep',JSON_OBJECT('contentKey','cs408-sequential-stack','title','顺序栈','description','继续学习数组如何用 top 维护栈顶。')),JSON_OBJECT('id','stack-lifo-v1','prompt','栈允许在哪个位置执行插入和删除？','options',JSON_ARRAY(JSON_OBJECT('id','TOP_ONLY','text','只能在栈顶操作'),JSON_OBJECT('id','BOTH_ENDS','text','可在栈顶和栈底任意操作')),'correctOptionId','TOP_ONLY','correctExplanation','正确：栈的受限访问规则是所有更新都发生在栈顶。','incorrectExplanation','不正确：两端都能操作的结构不是栈的 LIFO 约束。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-stack-lifo' AND existing.content_version=1 WHERE point.content_key='cs408-stack-lifo' AND existing.id IS NULL;
